vector<vector<int>> transpose(vector<vector<int>>& mat) {
    int n = mat.size();  

    // Traverse the upper triangle of the matrix
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {

            // Swap elements across the diagonal
            swap(mat[i][j], mat[j][i]);
        }
    }

    return mat;  
}

